package com.procurement.approvaltask.controller;import com.procurement.approvaltask.dto.request.*;import com.procurement.approvaltask.dto.response.*;import com.procurement.approvaltask.entity.*;import com.procurement.approvaltask.service.*;import com.procurement.common.response.*;import jakarta.validation.Valid;import org.springframework.data.domain.*;import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/approval-tasks")public class ApprovalTaskController{private final ApprovalTaskService service;public ApprovalTaskController(ApprovalTaskService s){service=s;}private Pageable p(int page,int size,String sort,String direction){return PageRequest.of(page,size,Sort.by(Sort.Direction.fromString(direction),sort));}@GetMapping public ApiResponse<PageResponse<ApprovalTaskResponse>>search(@RequestParam(required=false)Long purchaseRequestId,@RequestParam(required=false)Long assignedEmployeeId,@RequestParam(required=false)ApprovalTaskStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="assignedDate")String sort,@RequestParam(defaultValue="desc")String direction){return ApiResponse.success(service.search(purchaseRequestId,assignedEmployeeId,status,p(page,size,sort,direction)));}@GetMapping("/my-queue")public ApiResponse<PageResponse<ApprovalTaskQueueResponse>>myQueue(@RequestParam(required=false)ApprovalTaskStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){return ApiResponse.success(service.myQueue(status,p(page,size,"assignedDate","desc")));}@GetMapping("/my-authority")public ApiResponse<ApprovalAuthorityResponse>myAuthority(){return ApiResponse.success(service.myAuthority());}@GetMapping("/{id}")public ApiResponse<ApprovalTaskResponse>get(@PathVariable Long id){return ApiResponse.success(service.getById(id));}@PostMapping("/{id}/approve")@PreAuthorize("hasAuthority('CAN_APPROVE_PR')")public ApiResponse<ApprovalTaskResponse>approve(@PathVariable Long id,@Valid@RequestBody(required=false)ApprovalDecisionRequest r){return ApiResponse.success("Approval task approved",service.approve(id,r));}@PostMapping("/{id}/reject")@PreAuthorize("hasAuthority('CAN_REJECT_PR')")public ApiResponse<ApprovalTaskResponse>reject(@PathVariable Long id,@Valid@RequestBody(required=false)ApprovalDecisionRequest r){return ApiResponse.success("Approval task rejected",service.reject(id,r));}@PostMapping("/{id}/return")@PreAuthorize("hasAuthority('CAN_RETURN_PR')")public ApiResponse<ApprovalTaskResponse>returnTask(@PathVariable Long id,@Valid@RequestBody(required=false)ApprovalDecisionRequest r){return ApiResponse.success("Approval task returned",service.returnTask(id,r));}}
